package snippets.java.spring;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import jakarta.validation.Valid;
import java.util.List;

/**
 * Spring Boot REST Controller — Best Practices
 */
@RestController
@RequestMapping("/api/v1/users")
public class UserController {

    private final UserService userService;

    // Constructor injection (preferred over @Autowired)
    public UserController(UserService userService) {
        this.userService = userService;
    }

    @GetMapping
    public ResponseEntity<Page<UserDto>> getUsers(
            @RequestParam(defaultValue = "0") int page,
            @RequestParam(defaultValue = "20") int size,
            @RequestParam(defaultValue = "id") String sortBy) {
        Pageable pageable = PageRequest.of(page, size, Sort.by(sortBy));
        return ResponseEntity.ok(userService.findAll(pageable));
    }

    @GetMapping("/{id}")
    public ResponseEntity<UserDto> getUser(@PathVariable Long id) {
        return userService.findById(id)
            .map(ResponseEntity::ok)
            .orElseThrow(() -> new ResourceNotFoundException("User", id));
    }

    @PostMapping
    public ResponseEntity<UserDto> createUser(@Valid @RequestBody CreateUserRequest request) {
        UserDto created = userService.create(request);
        URI location = URI.create("/api/v1/users/" + created.getId());
        return ResponseEntity.created(location).body(created);
    }

    @PatchMapping("/{id}")
    public ResponseEntity<UserDto> updateUser(
            @PathVariable Long id,
            @Valid @RequestBody UpdateUserRequest request) {
        return ResponseEntity.ok(userService.update(id, request));
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteUser(@PathVariable Long id) {
        userService.delete(id);
        return ResponseEntity.noContent().build();
    }
}

// ---- Exception Handler ----
@RestControllerAdvice
class GlobalExceptionHandler {

    @ExceptionHandler(ResourceNotFoundException.class)
    public ResponseEntity<ErrorResponse> handleNotFound(ResourceNotFoundException ex) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
            .body(new ErrorResponse("NOT_FOUND", ex.getMessage()));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ErrorResponse> handleValidation(MethodArgumentNotValidException ex) {
        List<String> errors = ex.getBindingResult().getFieldErrors().stream()
            .map(fe -> fe.getField() + ": " + fe.getDefaultMessage())
            .toList();
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
            .body(new ErrorResponse("VALIDATION_FAILED", String.join(", ", errors)));
    }
}

package snippets.java.streams;

import java.util.*;
import java.util.stream.*;
import java.util.function.*;

/**
 * Java Stream API — Practical Patterns
 */
public class StreamPatterns {

    record Employee(String name, String dept, double salary) {}

    public static void main(String[] args) {
        List<Employee> employees = List.of(
            new Employee("Alice", "Engineering", 95000),
            new Employee("Bob",   "Engineering", 85000),
            new Employee("Carol", "Marketing",   75000),
            new Employee("Dave",  "Marketing",   80000),
            new Employee("Eve",   "Engineering", 120000)
        );

        // 1. Filter + Map + Collect
        List<String> highEarners = employees.stream()
            .filter(e -> e.salary() > 90000)
            .map(Employee::name)
            .sorted()
            .collect(Collectors.toList());
        System.out.println(highEarners); // [Alice, Eve]

        // 2. Group by department
        Map<String, List<Employee>> byDept = employees.stream()
            .collect(Collectors.groupingBy(Employee::dept));

        // 3. Average salary per department
        Map<String, Double> avgSalaryByDept = employees.stream()
            .collect(Collectors.groupingBy(Employee::dept,
                     Collectors.averagingDouble(Employee::salary)));
        System.out.println(avgSalaryByDept);

        // 4. Statistics
        DoubleSummaryStatistics stats = employees.stream()
            .mapToDouble(Employee::salary)
            .summaryStatistics();
        System.out.printf("Max: %.0f, Avg: %.0f%n", stats.getMax(), stats.getAverage());

        // 5. Partition by condition
        Map<Boolean, List<Employee>> partitioned = employees.stream()
            .collect(Collectors.partitioningBy(e -> e.salary() > 90000));

        // 6. FlatMap (flatten nested lists)
        List<List<Integer>> nested = List.of(List.of(1,2), List.of(3,4), List.of(5));
        List<Integer> flat = nested.stream().flatMap(Collection::stream).collect(Collectors.toList());
        System.out.println(flat); // [1,2,3,4,5]

        // 7. Reduce
        double totalSalary = employees.stream()
            .mapToDouble(Employee::salary)
            .reduce(0, Double::sum);

        // 8. Count by department
        Map<String, Long> countByDept = employees.stream()
            .collect(Collectors.groupingBy(Employee::dept, Collectors.counting()));

        // 9. String joining
        String names = employees.stream()
            .map(Employee::name)
            .collect(Collectors.joining(", ", "[", "]"));
        System.out.println(names); // [Alice, Bob, Carol, Dave, Eve]

        // 10. Custom Collector — top earner per dept
        Map<String, Optional<Employee>> topEarner = employees.stream()
            .collect(Collectors.groupingBy(Employee::dept,
                     Collectors.maxBy(Comparator.comparingDouble(Employee::salary))));
        topEarner.forEach((dept, emp) ->
            emp.ifPresent(e -> System.out.println(dept + ": " + e.name())));
    }
}

package snippets.java.concurrent;

import java.util.List;
import java.util.concurrent.*;
import java.util.stream.Collectors;

/**
 * CompletableFuture — Async Programming in Java
 */
public class CompletableFuturePatterns {

    private static final ExecutorService executor =
        Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    // 1. Basic async computation
    public static CompletableFuture<String> fetchUser(Long userId) {
        return CompletableFuture.supplyAsync(() -> {
            // simulate DB call
            return "User:" + userId;
        }, executor);
    }

    // 2. Chain (thenApply = map, thenCompose = flatMap)
    public static CompletableFuture<String> buildProfile(Long userId) {
        return fetchUser(userId)
            .thenApply(user -> user.toUpperCase())           // sync transform
            .thenCompose(user -> fetchOrders(user))          // async chain
            .thenApply(orders -> "Profile: " + orders);
    }

    private static CompletableFuture<String> fetchOrders(String user) {
        return CompletableFuture.supplyAsync(() -> user + "_ORDERS");
    }

    // 3. allOf — wait for all futures
    public static void fetchAll(List<Long> userIds) {
        List<CompletableFuture<String>> futures = userIds.stream()
            .map(CompletableFuturePatterns::fetchUser)
            .collect(Collectors.toList());

        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
            .thenRun(() -> {
                List<String> results = futures.stream()
                    .map(CompletableFuture::join)
                    .collect(Collectors.toList());
                System.out.println("All done: " + results);
            });
    }

    // 4. anyOf — first to complete wins
    public static CompletableFuture<Object> race(List<Long> userIds) {
        List<CompletableFuture<String>> futures = userIds.stream()
            .map(CompletableFuturePatterns::fetchUser)
            .collect(Collectors.toList());
        return CompletableFuture.anyOf(futures.toArray(new CompletableFuture[0]));
    }

    // 5. Error handling
    public static CompletableFuture<String> robustFetch(Long userId) {
        return fetchUser(userId)
            .exceptionally(ex -> "Default User")              // fallback on error
            .whenComplete((result, ex) -> {                   // always runs
                if (ex != null) System.err.println("Error: " + ex.getMessage());
                else System.out.println("Fetched: " + result);
            });
    }

    // 6. Timeout
    public static CompletableFuture<String> withTimeout(Long userId) {
        return fetchUser(userId)
            .orTimeout(5, TimeUnit.SECONDS)                   // Java 9+
            .exceptionally(ex -> "Timed out");
    }

    // 7. thenCombine — merge two futures
    public static CompletableFuture<String> fetchAndCombine(Long userId, Long orderId) {
        CompletableFuture<String> userFuture  = fetchUser(userId);
        CompletableFuture<String> orderFuture = fetchUser(orderId); // reusing for demo
        return userFuture.thenCombine(orderFuture,
            (user, order) -> user + " | Order: " + order);
    }

    public static void main(String[] args) throws Exception {
        // Run chain
        String profile = buildProfile(42L).get(5, TimeUnit.SECONDS);
        System.out.println(profile);

        // Fetch all
        fetchAll(List.of(1L, 2L, 3L));
        Thread.sleep(500);

        executor.shutdown();
    }
}

package snippets.java.collections;

import java.util.*;

/**
 * Java Collections Framework — Common Operations
 */
public class CollectionsCheatsheet {

    public static void main(String[] args) {

        // ---- ArrayList vs LinkedList ----
        // ArrayList: O(1) get, O(n) insert/delete at middle
        // LinkedList: O(n) get, O(1) insert/delete at ends
        List<String> list = new ArrayList<>(List.of("a", "b", "c"));
        list.add("d");          // O(1) amortized
        list.remove(0);         // O(n) shift
        list.sort(Comparator.reverseOrder());

        // ---- HashMap ----
        // O(1) avg get/put, O(n) worst (hash collision)
        Map<String, Integer> freq = new HashMap<>();
        String[] words = {"the", "cat", "sat", "on", "the", "mat"};
        for (String w : words) freq.merge(w, 1, Integer::sum);
        freq.forEach((k, v) -> System.out.printf("%s: %d%n", k, v));
        int count = freq.getOrDefault("the", 0);  // 2
        freq.computeIfAbsent("dog", k -> 0);

        // ---- TreeMap (sorted by key) ----
        TreeMap<Integer, String> treeMap = new TreeMap<>();
        treeMap.put(3, "c"); treeMap.put(1, "a"); treeMap.put(2, "b");
        System.out.println(treeMap.firstKey());             // 1
        System.out.println(treeMap.floorKey(2));            // 2
        System.out.println(treeMap.ceilingKey(2));          // 2
        System.out.println(treeMap.subMap(1, 3));           // {1=a, 2=b}

        // ---- PriorityQueue (MinHeap by default) ----
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        PriorityQueue<int[]> customHeap = new PriorityQueue<>(
            Comparator.comparingInt((int[] a) -> a[0]).thenComparingInt(a -> a[1]));

        // ---- Deque (Stack + Queue) ----
        Deque<Integer> deque = new ArrayDeque<>();
        deque.push(1);    // stack push (addFirst)
        deque.peek();     // stack top (peekFirst)
        deque.pop();      // stack pop (removeFirst)
        deque.offer(2);   // queue add (addLast)
        deque.poll();     // queue remove (removeFirst)

        // ---- LinkedHashMap (insertion-order) ----
        // LRU Cache base structure
        Map<String, Integer> lru = new LinkedHashMap<>(16, 0.75f, true) {
            protected boolean removeEldestEntry(Map.Entry<String, Integer> eldest) {
                return size() > 3; // keeps last 3 accessed
            }
        };

        // ---- Collections utility ----
        List<Integer> nums = new ArrayList<>(List.of(3,1,4,1,5,9,2,6));
        Collections.sort(nums);                            // [1,1,2,3,4,5,6,9]
        Collections.shuffle(nums);
        int pos = Collections.binarySearch(nums, 5);       // sorted needed
        System.out.println(Collections.frequency(nums, 1)); // 2
        System.out.println(Collections.max(nums));          // 9

        // ---- Arrays utility ----
        int[] arr = {5, 2, 8, 1, 9};
        Arrays.sort(arr);                                  // [1,2,5,8,9]
        System.out.println(Arrays.binarySearch(arr, 5));   // 2
        System.out.println(Arrays.toString(arr));
        int[][] matrix = {{3,1},{2,4}};
        Arrays.sort(matrix, Comparator.comparingInt(r -> r[0])); // sort by first col
    }
}

package snippets.java.concurrent;

import java.util.List;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * Java Executor Service — Thread Pool Patterns
 */
public class ExecutorPatterns {

    // 1. Fixed thread pool
    public static void fixedPool() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(4);
        for (int i = 0; i < 10; i++) {
            final int taskId = i;
            pool.submit(() -> {
                System.out.println("Task " + taskId + " on " + Thread.currentThread().getName());
            });
        }
        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);
    }

    // 2. Custom thread pool with rejection policy
    public static ThreadPoolExecutor customPool() {
        return new ThreadPoolExecutor(
            2,              // corePoolSize
            10,             // maximumPoolSize
            60, TimeUnit.SECONDS,    // keepAliveTime
            new LinkedBlockingQueue<>(100),          // work queue
            new ThreadFactory() {                    // custom thread naming
                AtomicInteger count = new AtomicInteger();
                public Thread newThread(Runnable r) {
                    Thread t = new Thread(r, "worker-" + count.incrementAndGet());
                    t.setDaemon(true);
                    return t;
                }
            },
            new ThreadPoolExecutor.CallerRunsPolicy() // on full queue: caller executes
        );
    }

    // 3. ScheduledExecutorService
    public static void scheduledTasks() {
        ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(2);

        // Run after 1s delay
        scheduler.schedule(() -> System.out.println("Delayed task"), 1, TimeUnit.SECONDS);

        // Run every 5s (fixed rate — regardless of execution time)
        scheduler.scheduleAtFixedRate(
            () -> System.out.println("Fixed rate: " + System.currentTimeMillis()),
            0, 5, TimeUnit.SECONDS);

        // Run 5s AFTER previous finishes (fixed delay)
        scheduler.scheduleWithFixedDelay(
            () -> System.out.println("Fixed delay"),
            0, 5, TimeUnit.SECONDS);
    }

    // 4. Callable + Future
    public static void futureExample() throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        Future<Integer> future = pool.submit(() -> {
            Thread.sleep(1000);
            return 42;
        });
        System.out.println("Working while future runs...");
        int result = future.get(5, TimeUnit.SECONDS); // blocks until done
        System.out.println("Result: " + result);
        pool.shutdown();
    }

    // 5. Semaphore — limit concurrent access
    public static void semaphoreExample() {
        Semaphore semaphore = new Semaphore(3); // max 3 concurrent
        for (int i = 0; i < 10; i++) {
            new Thread(() -> {
                try {
                    semaphore.acquire();
                    System.out.println(Thread.currentThread().getName() + " running");
                    Thread.sleep(1000);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                } finally {
                    semaphore.release();
                }
            }).start();
        }
    }

    // 6. CountDownLatch and CyclicBarrier
    public static void latchExample() throws InterruptedException {
        int N = 3;
        CountDownLatch latch = new CountDownLatch(N);
        for (int i = 0; i < N; i++) {
            new Thread(() -> { latch.countDown(); System.out.println("Worker done"); }).start();
        }
        latch.await(); // main waits until all workers done
        System.out.println("All workers finished");
    }

    public static void main(String[] args) throws Exception {
        fixedPool();
        futureExample();
    }
}

package snippets.java.patterns;

import java.util.*;

/**
 * Structural Design Patterns in Java
 */
public class StructuralPatterns {

    // ---- 1. Decorator Pattern ----
    interface Coffee { double cost(); String description(); }

    static class SimpleCoffee implements Coffee {
        public double cost() { return 1.0; }
        public String description() { return "Coffee"; }
    }

    static abstract class CoffeeDecorator implements Coffee {
        protected Coffee coffee;
        CoffeeDecorator(Coffee c) { this.coffee = c; }
    }

    static class MilkDecorator extends CoffeeDecorator {
        MilkDecorator(Coffee c) { super(c); }
        public double cost() { return coffee.cost() + 0.25; }
        public String description() { return coffee.description() + ", Milk"; }
    }

    static class SugarDecorator extends CoffeeDecorator {
        SugarDecorator(Coffee c) { super(c); }
        public double cost() { return coffee.cost() + 0.10; }
        public String description() { return coffee.description() + ", Sugar"; }
    }

    // ---- 2. Adapter Pattern ----
    interface USPlug { void plugInUS(); }
    interface EUPlug { void plugInEU(); }

    static class USDevice implements USPlug {
        public void plugInUS() { System.out.println("US device plugged in"); }
    }

    static class EUAdapter implements EUPlug {
        private final USPlug device;
        EUAdapter(USPlug d) { this.device = d; }
        public void plugInEU() {
            System.out.println("Adapting...");
            device.plugInUS();
        }
    }

    // ---- 3. Facade Pattern ----
    static class HomeTheaterFacade {
        private Amplifier amp;
        private DVDPlayer dvd;
        private Projector projector;

        HomeTheaterFacade(Amplifier a, DVDPlayer d, Projector p) { amp=a; dvd=d; projector=p; }

        void watchMovie(String movie) {
            projector.on(); projector.setInput("DVD");
            amp.on(); amp.setVolume(10);
            dvd.on(); dvd.play(movie);
        }

        void endMovie() { dvd.off(); amp.off(); projector.off(); }
    }

    // Placeholder classes for Facade demo
    static class Amplifier { void on(){} void off(){} void setVolume(int v){} }
    static class DVDPlayer { void on(){} void off(){} void play(String m){} }
    static class Projector { void on(){} void off(){} void setInput(String s){} }

    // ---- 4. Proxy Pattern ----
    interface Image { void display(); }

    static class RealImage implements Image {
        private String filename;
        RealImage(String f) { this.filename = f; loadFromDisk(); }
        private void loadFromDisk() { System.out.println("Loading " + filename); }
        public void display() { System.out.println("Displaying " + filename); }
    }

    static class LazyImageProxy implements Image {
        private String filename;
        private RealImage realImage;
        LazyImageProxy(String f) { this.filename = f; }
        public void display() {
            if (realImage == null) realImage = new RealImage(filename); // lazy load
            realImage.display();
        }
    }

    public static void main(String[] args) {
        // Decorator
        Coffee c = new SugarDecorator(new MilkDecorator(new SimpleCoffee()));
        System.out.println(c.description() + " $" + c.cost()); // Coffee, Milk, Sugar $1.35

        // Adapter
        EUPlug adapter = new EUAdapter(new USDevice());
        adapter.plugInEU();

        // Proxy
        Image img = new LazyImageProxy("photo.png");
        img.display(); // loads now
        img.display(); // already loaded
    }
}

package snippets.java.spring;

import jakarta.persistence.*;
import org.springframework.data.domain.*;
import org.springframework.data.jpa.repository.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;

// ---- Entity ----
@Entity
@Table(name = "orders")
public class Order {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false)
    private String customerId;

    @Enumerated(EnumType.STRING)
    private OrderStatus status;

    @OneToMany(mappedBy = "order", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<OrderItem> items = new ArrayList<>();

    @Version  // optimistic locking
    private int version;

    public void addItem(OrderItem item) { items.add(item); item.setOrder(this); }
    public void removeItem(OrderItem item) { items.remove(item); item.setOrder(null); }

    // getters/setters omitted for brevity
}

// ---- Repository ----
public interface OrderRepository extends JpaRepository<Order, Long> {

    // Derived queries
    List<Order> findByCustomerIdOrderByCreatedAtDesc(String customerId);
    Optional<Order> findByIdAndCustomerId(Long id, String customerId);

    // JPQL
    @Query("SELECT o FROM Order o WHERE o.status = :status AND SIZE(o.items) > 0")
    List<Order> findActiveOrdersWithItems(@Param("status") OrderStatus status);

    // Native SQL
    @Query(value = "SELECT * FROM orders WHERE created_at > NOW() - INTERVAL '7 days'",
           nativeQuery = true)
    List<Order> findRecentOrders();

    // Paging
    Page<Order> findByStatus(OrderStatus status, Pageable pageable);

    // Count
    long countByCustomerId(String customerId);

    // Bulk update
    @Modifying
    @Query("UPDATE Order o SET o.status = 'CANCELLED' WHERE o.customerId = :cid AND o.status = 'PENDING'")
    int cancelPendingOrdersByCustomer(@Param("cid") String customerId);
}

// ---- Service ----
@Service
@Transactional(readOnly = true)  // default read-only; write methods override
public class OrderService {
    private final OrderRepository repo;
    OrderService(OrderRepository repo) { this.repo = repo; }

    @Transactional
    public Order createOrder(String customerId, List<OrderItem> items) {
        Order order = new Order();
        order.setCustomerId(customerId);
        order.setStatus(OrderStatus.PENDING);
        items.forEach(order::addItem);
        return repo.save(order);
    }

    public Page<Order> getOrders(OrderStatus status, int page, int size) {
        return repo.findByStatus(status, PageRequest.of(page, size, Sort.by("id").descending()));
    }

    @Transactional
    public Order updateStatus(Long id, OrderStatus newStatus) {
        Order order = repo.findById(id).orElseThrow(() -> new IllegalArgumentException("Order not found"));
        order.setStatus(newStatus);
        return order; // dirty checking — auto-saved on commit
    }
}

enum OrderStatus { PENDING, CONFIRMED, SHIPPED, DELIVERED, CANCELLED }

package snippets.java.functional;

import java.util.*;
import java.util.function.*;
import java.util.stream.*;

/**
 * Java Functional Programming Patterns
 */
public class FunctionalPatterns {

    // 1. Function composition
    public static <A,B,C> Function<A,C> compose(Function<A,B> f, Function<B,C> g) {
        return f.andThen(g);
    }

    // 2. Currying
    public static <A,B,C> Function<A, Function<B,C>> curry(BiFunction<A,B,C> f) {
        return a -> b -> f.apply(a, b);
    }

    // 3. Memoization
    public static <K,V> Function<K,V> memoize(Function<K,V> fn) {
        Map<K,V> cache = new HashMap<>();
        return key -> cache.computeIfAbsent(key, fn);
    }

    // 4. Retry decorator
    public static <T> Supplier<T> withRetry(Supplier<T> supplier, int maxAttempts) {
        return () -> {
            RuntimeException last = null;
            for (int i = 0; i < maxAttempts; i++) {
                try { return supplier.get(); }
                catch (RuntimeException e) { last = e; }
            }
            throw last;
        };
    }

    // 5. Pipeline builder using Function
    static class Pipeline<T> {
        private final Function<T, T> steps;
        private Pipeline(Function<T,T> fn) { this.steps = fn; }
        public static <T> Pipeline<T> start() { return new Pipeline<>(Function.identity()); }
        public Pipeline<T> then(Function<T,T> step) { return new Pipeline<>(steps.andThen(step)); }
        public T execute(T input) { return steps.apply(input); }
    }

    public static void main(String[] args) {
        // Function composition
        Function<String, String>  trim  = String::trim;
        Function<String, String>  upper = String::toUpperCase;
        Function<String, Integer> len   = String::length;
        Function<String, Integer> pipeline = trim.andThen(upper).andThen(len);
        System.out.println(pipeline.apply("  hello  ")); // 5

        // Currying
        Function<Integer, Function<Integer, Integer>> add = curry(Integer::sum);
        Function<Integer, Integer> add5 = add.apply(5);
        System.out.println(add5.apply(3));  // 8
        System.out.println(add5.apply(10)); // 15

        // Memoization
        Function<Integer, Long> fib = memoize(n -> {
            if (n <= 1) return (long) n;
            // Note: can't self-reference here without externalized memo
            return (long) n; // simplified
        });

        // Pipeline
        String result = Pipeline.<String>start()
            .then(String::trim)
            .then(String::toLowerCase)
            .then(s -> s.replace(" ", "_"))
            .execute("  Hello World  ");
        System.out.println(result); // hello_world

        // Predicate composition
        Predicate<Integer> isEven = n -> n % 2 == 0;
        Predicate<Integer> isPos  = n -> n > 0;
        List<Integer> nums = List.of(-4,-1,0,2,3,6,8);
        List<Integer> evenPositive = nums.stream()
            .filter(isEven.and(isPos))
            .collect(Collectors.toList());
        System.out.println(evenPositive); // [2, 6, 8]
    }
}

package snippets.java.functional;

import java.util.Optional;

/**
 * Optional — Null-safe Java Patterns
 */
public class OptionalPatterns {

    record Address(String city, String country) {}
    record User(String name, Address address) {}

    // BAD: null-check hell
    static String getCityBad(User user) {
        if (user != null) {
            Address addr = user.address();
            if (addr != null) return addr.city();
        }
        return "Unknown";
    }

    // GOOD: Optional chains
    static Optional<String> getCity(User user) {
        return Optional.ofNullable(user)
            .map(User::address)
            .map(Address::city);
    }

    // Core API
    static void coreApi() {
        Optional<String> name = Optional.of("Alice");
        Optional<String> empty = Optional.empty();
        Optional<String> nullable = Optional.ofNullable(null);

        // Extract value
        name.get();                      // "Alice" (throws if empty)
        name.orElse("Default");          // "Alice"
        empty.orElse("Default");         // "Default"
        empty.orElseGet(() -> computeDefault());  // lazy
        empty.orElseThrow(() -> new IllegalStateException("Missing"));

        // Transform
        name.map(String::toUpperCase);          // Optional["ALICE"]
        name.flatMap(v -> Optional.of(v + "!"));
        name.filter(v -> v.length() > 3);       // Optional["Alice"]

        // Check
        name.isPresent();  // true
        name.isEmpty();    // false (Java 11+)
        name.ifPresent(v -> System.out.println("Name: " + v));
        name.ifPresentOrElse(    // Java 9+
            v -> System.out.println("Found: " + v),
            () -> System.out.println("Not found")
        );

        // Fallback chain (Java 9+)
        Optional<String> result = empty
            .or(() -> Optional.of("fallback"));  // Optional["fallback"]
    }

    // Repository pattern example
    static Optional<User> findUser(Long id) {
        // Simulate DB lookup
        return id == 1L ? Optional.of(new User("Alice", new Address("London", "UK")))
                        : Optional.empty();
    }

    private static String computeDefault() { return "computed"; }

    public static void main(String[] args) {
        // Usage
        User alice  = new User("Alice", new Address("London", "UK"));
        User noAddr = new User("Bob", null);

        System.out.println(getCity(alice).orElse("Unknown"));  // London
        System.out.println(getCity(noAddr).orElse("Unknown")); // Unknown
        System.out.println(getCity(null).orElse("Unknown"));   // Unknown

        // Chain with service call
        findUser(1L)
            .map(User::address)
            .map(Address::city)
            .ifPresentOrElse(
                city -> System.out.println("City: " + city),
                () -> System.out.println("User not found")
            );
    }
}

package snippets.java.spring;

import io.jsonwebtoken.*;
import io.jsonwebtoken.security.Keys;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
import org.springframework.web.filter.OncePerRequestFilter;
import jakarta.servlet.FilterChain;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.security.Key;
import java.util.Date;

/**
 * JWT Security — Spring Boot Configuration
 */
public class JwtSecurityConfig {

    // ---- JWT Utility ----
    public static class JwtUtil {
        private static final Key SECRET = Keys.secretKeyFor(SignatureAlgorithm.HS256);
        private static final long EXPIRY = 15 * 60 * 1000L; // 15 min

        public static String generateToken(String userId, String role) {
            return Jwts.builder()
                .setSubject(userId)
                .claim("role", role)
                .setIssuedAt(new Date())
                .setExpiration(new Date(System.currentTimeMillis() + EXPIRY))
                .signWith(SECRET)
                .compact();
        }

        public static Claims validateToken(String token) {
            return Jwts.parserBuilder()
                .setSigningKey(SECRET)
                .build()
                .parseClaimsJws(token)
                .getBody();
        }

        public static String getUserId(String token) {
            return validateToken(token).getSubject();
        }
    }

    // ---- JWT Filter ----
    public static class JwtAuthFilter extends OncePerRequestFilter {
        @Override
        protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res,
                                        FilterChain chain) throws java.io.IOException, jakarta.servlet.ServletException {
            String header = req.getHeader("Authorization");
            if (header != null && header.startsWith("Bearer ")) {
                String token = header.substring(7);
                try {
                    Claims claims = JwtUtil.validateToken(token);
                    // Set authentication in SecurityContext
                    var auth = new org.springframework.security.authentication.UsernamePasswordAuthenticationToken(
                        claims.getSubject(), null, java.util.Collections.emptyList());
                    org.springframework.security.core.context.SecurityContextHolder
                        .getContext().setAuthentication(auth);
                } catch (JwtException e) {
                    res.sendError(HttpServletResponse.SC_UNAUTHORIZED, "Invalid token");
                    return;
                }
            }
            chain.doFilter(req, res);
        }
    }

    // ---- Security Filter Chain ----
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        return http
            .csrf(csrf -> csrf.disable())
            .sessionManagement(s -> s.sessionCreationPolicy(
                org.springframework.security.config.http.SessionCreationPolicy.STATELESS))
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/auth/**").permitAll()
                .requestMatchers("/api/admin/**").hasRole("ADMIN")
                .anyRequest().authenticated()
            )
            .addFilterBefore(new JwtAuthFilter(), UsernamePasswordAuthenticationFilter.class)
            .build();
    }
}
